def clean(df):
    df = df.drop_duplicates().copy()
    df = df.dropna(subset=['Region'])
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    return df

def answer(df):
    grouped = df.dropna(subset=['Region']).groupby('Region')['Quantity'].sum()
    return {str(k): int(v) if pd.notna(v) and float(v).is_integer() else v for k, v in sorted(grouped.items())}
